#!/usr/bin/env python3
"""Build the web app's generated files.

Writes:
  docs/app/defaults.js  the example sites the app starts with, from config/operation.example.json
  docs/sw.js            the offline service worker, versioned by a hash of every app file

Usage:
  python3 scripts/build.py           regenerate the files
  python3 scripts/build.py --check   fail if they are out of date (CI)
"""

import hashlib
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
DOCS = ROOT / 'docs'
EXAMPLE = ROOT / 'config' / 'operation.example.json'
DEFAULTS = DOCS / 'app' / 'defaults.js'
SW = DOCS / 'sw.js'
SW_TEMPLATE = ROOT / 'scripts' / 'sw.template.js'


def defaults_text():
    cfg = json.loads(EXAMPLE.read_text(encoding='utf-8'))
    keep = {k: cfg[k] for k in ('anchors', 'goals', 'sites') if k in cfg}
    body = json.dumps(keep, indent=2, ensure_ascii=False)
    return ('/* Generated by scripts/build.py from config/operation.example.json. Do not edit by hand. */\n'
            'export const EXAMPLE = ' + body + ';\n')


def assets():
    """Everything the installed app needs offline. sw.js is the worker itself and is never cached.
    Every file in docs/app, docs/fonts and docs/icons is included, so new ones work offline unlisted."""
    files = ['index.html', 'styles.css', 'manifest.webmanifest']
    for folder, pattern in (('app', '*.js'), ('fonts', '*.woff2'), ('icons', '*.png')):
        found = {f'{folder}/{p.name}' for p in (DOCS / folder).glob(pattern)}
        if folder == 'app':
            found.add('app/defaults.js')   # generated by this script, so listed even before it exists
        files += sorted(found)
    return files


def sw_text(defaults):
    digest = hashlib.sha256()
    for path in assets():
        data = defaults.encode('utf-8') if path == 'app/defaults.js' else (DOCS / path).read_bytes()
        digest.update(path.encode('utf-8') + b'\0' + data + b'\0')
    template = SW_TEMPLATE.read_text(encoding='utf-8')
    return template.replace("'__VERSION__'", json.dumps(digest.hexdigest()[:12])).replace('__ASSETS__', json.dumps(assets()))


def main():
    defaults = defaults_text()
    outputs = {DEFAULTS: defaults, SW: sw_text(defaults)}
    if '--check' in sys.argv[1:]:
        stale = [p for p, text in outputs.items() if not p.exists() or p.read_text(encoding='utf-8') != text]
        if stale:
            print('Out of date: ' + ', '.join(str(p.relative_to(ROOT)) for p in stale) + '. Run: python3 scripts/build.py')
            return 1
        print('Generated files are up to date.')
        return 0
    for path, text in outputs.items():
        path.write_text(text, encoding='utf-8')
        print('wrote', path.relative_to(ROOT))
    return 0


if __name__ == '__main__':
    sys.exit(main())
